/** Every known Greenhouse board, as { identifier, name }. */
export const GREENHOUSE_BOARDS = BLOB.split('\n').map((line) => {
  const tab = line.indexOf('\t');
  return { identifier: line.slice(0, tab), name: line.slice(tab + 1) };
});
